draw(squiggly(B--C, 5.050, 15), pp);

draw(squiggly(B--D, 4.04, 20), pp);

draw(squiggly(C--D, 2.718, 20), pp);

draw(squiggly(D--E, 2.718, -60), pp);[/asy]
